namespace ghidra.app.plugin.core.debug.gui.modules;





using docking;
using docking;
using ghidra.trace.model.modules;

public class DebuggerSectionActionContext : DefaultActionContext {
	private Set<TraceSection> selectedSections;
	private bool forcedSingle;

	public DebuggerSectionActionContext(ComponentProvider provider,
			Set<TraceSection> selected, Component sourceComponent, bool forcedSingle) : base(provider, selected, sourceComponent)
    {
		this.selectedSections = selected;
		this.forcedSingle = forcedSingle;
	}

	public Set<TraceSection> getSelectedSections(bool allowExpansion, long snap) {
		if (forcedSingle && allowExpansion) {
			return selectedSections.stream()
					.flatMap(s => s.getModule().getSections(snap).stream())
					.collect(Collectors.toUnmodifiableSet());
		}
		return selectedSections;
	}

	public bool isForcedSingle() {
		return forcedSingle;
	}
}
